import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const MESSAGE = 'אני מתפלל עם האפליקציה אור הגאולה — זמני תפילה, הנוסח שלי ותזכורות. מצטרף להתחזק איתי?';
const LINK = 'https://zichui-harabim.expo.app/?invite=c750744f-6d79-4dd5-a891-0b3446eb08cd';

test.describe('«מפת השפעה» и приглашение', () => {
  test('IM-01 «הזמנת אדם להתחזק» — утверждённый текст в окне и в navigator.share, одна ссылка; «ביטול» ничего не отправляет #6a86f7e6 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: подменить navigator.share (payload → window.__shares), canShare = () => true.
    await page.addInitScript(() => {
      const w = window as any;
      w.__shares = [];
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: (data: unknown) => {
          w.__shares.push(data);
          return Promise.resolve();
        },
      });
      Object.defineProperty(navigator, 'canShare', { configurable: true, value: () => true });
    });

    // 2. Открыть `/journey` → в блоке «מפת השפעה» нажать «הזמנת אדם להתחזק».
    await page.goto('/journey');
    const invite = page.getByRole('button', { name: 'הזמנת אדם להתחזק' });
    await expect(invite).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await invite.click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toContainText('הזמנת אדם להתחזק');
    await expect(dialog).toContainText('זו ההודעה שתישלח, בלי שום פרט נוסף:');
    await expect(dialog).toContainText(MESSAGE);
    await expect(dialog).toContainText(LINK);
    await expect(dialog.getByRole('button', { name: 'ביטול' })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'המשך לשיתוף' })).toBeVisible();

    // 3. Нажать «ביטול».
    await dialog.getByRole('button', { name: 'ביטול' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__shares.length)).toBe(0);

    // 4. Снова «הזמנת אדם להתחזק» → «המשך לשיתוף».
    await invite.click();
    await page.getByRole('dialog').getByRole('button', { name: 'המשך לשיתוף' }).click();
    await expect.poll(() => page.evaluate(() => (window as any).__shares.length)).toBe(1);
    const share = await page.evaluate(() => (window as any).__shares[0] as { text?: string; url?: string; message?: string });
    const full = [share.text ?? share.message ?? '', share.url ?? ''].join('\n');
    expect(full).toContain(MESSAGE);
    expect(full.split(LINK).length - 1).toBe(1);
    expect(full).not.toContain('אפליקציית');
  });
});
